class Solution {
    public int findKthNumber(int m, int n, int k) {
        int rows = Math.min(m, n);
        int cols = Math.max(m, n);
        int low = 1;
        int high = rows * cols;
        while (low < high) {
            int mid = low + (high - low) / 2;
            if (countLessOrEqual(mid, rows, cols) < k) {
                low = mid + 1;
            } else {
                high = mid;
            }
        }
        return low;
    }

    private long countLessOrEqual(int value, int rows, int cols) {
        long count = 0;
        for (int row = 1; row <= rows; row++) {
            count += Math.min(cols, value / row);
        }
        return count;
    }
}

class Solution {
    public int findKthNumber(int m, int n, int k) {
        int rows = Math.min(m, n);
        int cols = Math.max(m, n);
        int left = 1;
        int right = rows * cols;
        while (left < right) {
            int mid = left + (right - left) / 2;
            if (hasAtLeastK(mid, rows, cols, k)) {
                right = mid;
            } else {
                left = mid + 1;
            }
        }
        return left;
    }

    private boolean hasAtLeastK(int value, int rows, int cols, int k) {
        long count = 0;
        for (int row = 1; row <= rows; row++) {
            count += Math.min(cols, value / row);
            if (count >= k) {
                return true;
            }
        }
        return false;
    }
}

class Solution {
    public int findKthNumber(int m, int n, int k) {
        int low = 1;
        int high = m * n;
        while (low < high) {
            int mid = low + (high - low) / 2;
            if (hasAtLeastK(mid, m, n, k)) {
                high = mid;
            } else {
                low = mid + 1;
            }
        }
        return low;
    }

    private boolean hasAtLeastK(int value, int m, int n, int k) {
        int row = m;
        int col = 1;
        long count = 0;
        while (row >= 1 && col <= n) {
            if ((long) row * col <= value) {
                count += row;
                if (count >= k) {
                    return true;
                }
                col++;
            } else {
                row--;
            }
        }
        return false;
    }
}

class Solution {
    public int findKthNumber(int m, int n, int k) {
        int rows = Math.min(m, n);
        int cols = Math.max(m, n);
        int left = 1;
        int right = rows * cols;
        while (left < right) {
            int mid = left + (right - left) / 2;
            if (countGrouped(mid, rows, cols) >= k) {
                right = mid;
            } else {
                left = mid + 1;
            }
        }
        return left;
    }

    private long countGrouped(int value, int rows, int cols) {
        int fullRows = Math.min(rows, value / cols);
        long count = (long) fullRows * cols;
        int row = fullRows + 1;
        while (row <= rows && row <= value) {
            int quotient = value / row;
            if (quotient == 0) {
                break;
            }
            int lastRow = Math.min(rows, value / quotient);
            count += (long) (lastRow - row + 1) * quotient;
            row = lastRow + 1;
        }
        return count;
    }
}
